180		// la ÚNICA señal proactiva que tiene el core sobre su propia carga.
181		//
182		// Antes de esto, un módulo con un bug podía llevar al core a 154 % de CPU y
183		// 10 GB sin que nada lo dijera: `HealthLogger` y el log por petición están
184		// detrás de `LOG_LEVEL=debug` (apagado en producción), las cuentas del rate
185		// limiter no las leía nadie y `getPendingCount()` no se llamaba desde ningún
186		// sitio. La primera noticia fue un usuario diciendo «no funciona».
187		//
188		// Va a `info` y una vez por minuto a propósito: es una línea por minuto, no un
189		// volcado por petición, así que se puede dejar encendida en producción — que es
190		// el único sitio donde sirve de algo.
191		setInterval(() => {
192			const swept = defaultRateLimiter.sweepStaleBuckets() + interactionRateLimiter.sweepStaleBuckets();
193			if (swept > 0) {
194				logger.debug(LogType.GRPC, `[RateLimiter] swept ${swept} stale bucket(s)`);
195			}
196	
197			const general = defaultRateLimiter.drainMetrics();
198			const interactions = interactionRateLimiter.drainMetrics();
199			const inFlight = pendingRequestsSnapshot();
200			const allowed = general.allowed + interactions.allowed;
201			const blocked = general.blocked + interactions.blocked;
202			// Pico de CONCURRENCIA por módulo y rechazos por el techo. Es el número con el
203			// que se calibra `MAX_IN_FLIGHT_PER_MODULE`: si en semanas nunca pasa de dos
204			// dígitos, el techo de 256 sobra; si se acerca, hay que mirar qué módulo.
205			const concurrencyPeak = Math.max(general.inFlightPeak, interactions.inFlightPeak);
206			const concurrencyRejected = general.inFlightRejected + interactions.inFlightRejected;
