	/**
	 * Bounded so the ring can't grow under a sustained stream of late
	 * successes. 256 is a comfortable upper bound for the rate at which
	 * a worker might legitimately be late (we keep the most recent 256).
	 */
	private static readonly LATE_SUCCESS_MAX = 256;
	/**
	 * Techo de `pendingRequests`. Cada entrada retiene los closures
	 * resolve/reject, un `Timeout` y — vivo en el cierre de quien llamó a
	 * `trackRequest` — el payload de la petición, hasta 16 MiB por
	 * `max_receive_message_length` (server.ts). Sin techo, si las peticiones
	 * entran más rápido de lo que el worker resuelve el Map crece hasta donde
	 * aguante el heap: es el hallazgo #1 de AUDITORIA-limites-grpc-2026-08-11.md.
	 *
	 * `GrpcRateLimiter` ya limita a `MAX_IN_FLIGHT_PER_MODULE` (256) la
	 * concurrencia admitida por módulo, pero un mismo GrpcService (y por tanto
	 * un mismo RequestTracker) recibe tráfico de los ~10 módulos a la vez, así
	 * que el peor caso ya admitido ronda 2500. 5000 deja margen sobre eso sin
	 * dejar de ser un techo real.
	 */
	private static readonly DEFAULT_MAX_PENDING = 5000;
	private readonly defaultTimeout: number;
	private readonly maxPending: number;
	/** Peticiones rechazadas de entrada por tocar `maxPending`. */
	private droppedRequests = 0;
	private onSettle?: (request_id: string) => void;
	private onLateSuccess?: (request_id: string, response: MessageResponseIPC) => void;

	constructor(defaultTimeout = 30000, maxPending = RequestTracker.DEFAULT_MAX_PENDING) {
		// 30 seconds default
		this.defaultTimeout = defaultTimeout;
		this.maxPending = maxPending;
		// Se apunta al registro para que la profundidad de la cola sea medible sin
		// abrir un getter en cada servicio. Los trackers viven lo que el proceso, así
		// que no hace falta darse de baja.
		liveTrackers.add(this);
	}

