// Import via require so vitest doesn't try to resolve the `.js` extension
// from the source — the file lives in `dist/`. This matches the pattern
// other pre-existing tests in this repo use to load compiled modules.
import { createRequire } from "node:module";
import type { MessageResponseIPC } from "@kena/shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const require = createRequire(import.meta.url);
const { RequestTracker, pendingRequestsSnapshot } =
	require("../../../../dist/cluster/master/ipc/RequestTracker.js") as typeof import("../../../../dist/cluster/master/ipc/RequestTracker.js");

/**
 * AUDITORIA-limites-grpc-2026-08-11.md, hallazgo #1: `pendingRequests` no
 * tenía `maxPending`. Cada entrada retiene closures, un `Timeout` y el
 * payload de la petición mientras se espera al worker, así que sin techo el
 * Map crece sin control cuando las peticiones entran más rápido de lo que se
 * resuelven.
 */
describe("RequestTracker.maxPending", () => {
	let tracker: RequestTracker;

	beforeEach(() => {
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("rejects new requests once the pending queue hits maxPending, without touching older entries", async () => {
		tracker = new RequestTracker(30000, 2);

		const first = tracker.trackRequest("trace-1");
		const second = tracker.trackRequest("trace-2");
		expect(tracker.getPendingCount()).toBe(2);

		// A third request arrives while the queue is full — it must be
		// rejected immediately instead of joining the Map.
		await expect(tracker.trackRequest("trace-3")).rejects.toThrow(/pending queue full/);
		expect(tracker.getPendingCount()).toBe(2);
		expect(tracker.getDroppedCount()).toBe(1);

		// The two requests admitted before the cap are untouched.
		const response: MessageResponseIPC = {
			success: true,
			data: {},
			timestamp: new Date().toISOString(),
			request_id: "trace-1"
		} as any;
		expect(tracker.resolveRequest("trace-1", response)).toBe(true);
		await expect(first).resolves.toEqual(response);

		tracker.rejectRequest("trace-2", new Error("cleanup"));
		await expect(second).rejects.toThrow("cleanup");
	});

	it("frees a slot as soon as a pending request settles, so the next arrival is admitted", async () => {
		tracker = new RequestTracker(30000, 1);

		const first = tracker.trackRequest("trace-1");
		await expect(tracker.trackRequest("trace-2")).rejects.toThrow(/pending queue full/);

		tracker.rejectRequest("trace-1", new Error("done"));
		await expect(first).rejects.toThrow("done");

		expect(tracker.getPendingCount()).toBe(0);
		const third = tracker.trackRequest("trace-3");
		expect(tracker.getPendingCount()).toBe(1);
		tracker.rejectRequest("trace-3", new Error("cleanup"));
		await expect(third).rejects.toThrow("cleanup");
	});

	it("defaults to a bounded cap even when the constructor is called with no maxPending", async () => {
		tracker = new RequestTracker();
		expect(tracker.getPendingCount()).toBe(0);
		// Sanity: a handful of requests well under the default cap are all
		// admitted normally.
		for (let i = 0; i < 10; i++) {
			tracker.trackRequest(`trace-${i}`);
		}
		expect(tracker.getPendingCount()).toBe(10);
		expect(tracker.getDroppedCount()).toBe(0);
		tracker.clearAll();
	});

	it("pendingRequestsSnapshot aggregates dropped counts across trackers", async () => {
		tracker = new RequestTracker(30000, 1);
		tracker.trackRequest("trace-1");
		await expect(tracker.trackRequest("trace-2")).rejects.toThrow(/pending queue full/);

		const snapshot = pendingRequestsSnapshot();
		expect(snapshot.dropped).toBeGreaterThanOrEqual(1);

		tracker.clearAll();
	});
});

