## 💡 Ejemplos de Uso

### Ejemplo 1: Comunicación IPC Master-Worker

```typescript
// En ClusterIPC (Master)
class ClusterIPC {
	private requestTracker = new RequestTracker(30000);

	async sendToWorker(workerId: number, command: string, data: any): Promise<StandardResponse> {
		const request_id = `${workerId}-${Date.now()}-${Math.random()}`;

		// Iniciar rastreo
		const responsePromise = this.requestTracker.trackRequest(request_id, 10000);

		// Enviar mensaje al worker
		this.workers[workerId].send({
			type: "REQUEST",
			request_id,
			command,
			data
		});

		// Esperar respuesta
		return await responsePromise;
	}

	handleWorkerResponse(message: any) {
		// Cuando llega respuesta del worker
		this.requestTracker.resolveRequest(message.request_id, message.response);
	}
}
```

### Ejemplo 2: Manejo de Errores

```typescript
async function executeCommand(tracker: RequestTracker) {
	const request_id = "cmd-001";

	try {
		const response = await tracker.trackRequest(request_id, 5000);

		if (response.success) {
			console.log("Comando ejecutado:", response.data);
		} else {
			console.error("Comando falló:", response.error);
		}
	} catch (error) {
		// Timeout o error de red
		console.error("No se pudo ejecutar el comando:", error.message);
	}
}
```

### Ejemplo 3: Múltiples Solicitudes Concurrentes

```typescript
async function broadcastToWorkers(tracker: RequestTracker, workers: Worker[]) {
	const promises = workers.map((worker, index) => {
		const request_id = `broadcast-${index}`;

		// Enviar a cada worker
		worker.send({ type: "PING", request_id });

		// Rastrear respuesta
		return tracker.trackRequest(request_id, 2000).catch((err) => ({ success: false, error: err.message }));
	});

	// Esperar todas las respuestas (o timeouts)
	const results = await Promise.all(promises);

	const successCount = results.filter((r) => r.success).length;
	console.log(`${successCount}/${workers.length} workers respondieron`);
}
```

